#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#include <queue>
using namespace std;

const int U = 1 << 29;
const int LIM = 500;

struct Link {
    int u, v, cap, flow;
};

bool free_spots[11][11];
vector<int> g[LIM];
vector<Link> el;
int level_[LIM], idx[LIM], grid_dim, ex_r, ex_c, max_time, step_cnt[11][11], flow_cap[11][11];

int shortest_path(int sr, int sc, int tr, int tc) {
    queue<pair<int, pair<int, int>>> q;
    q.push({0, {sr, sc}});
    int d[11][11];
    for (int i = 0; i < grid_dim; ++i)
        for (int j = 0; j < grid_dim; ++j)
            d[i][j] = U;
    while (!q.empty()) {
        int dist = q.front().first;
        int r = q.front().second.first;
        int c = q.front().second.second;
        q.pop();
        d[r][c] = dist;
        if (r > 0 && free_spots[r-1][c]) {
            int nr = r - 1, nc = c;
            if (d[nr][nc] > dist + 1) {
                bool cond1 = (nr == tr && nc == tc && step_cnt[nr][nc] >= dist + 1);
                bool cond2 = (!(nr == tr && nc == tc) && step_cnt[nr][nc] > dist + 1);
                if (cond1 || cond2) q.push({dist + 1, {nr, nc}});
            }
        }
        if (c > 0 && free_spots[r][c-1]) {
            int nr = r, nc = c - 1;
            if (d[nr][nc] > dist + 1) {
                bool cond1 = (nr == tr && nc == tc && step_cnt[nr][nc] >= dist + 1);
                bool cond2 = (!(nr == tr && nc == tc) && step_cnt[nr][nc] > dist + 1);
                if (cond1 || cond2) q.push({dist + 1, {nr, nc}});
            }
        }
        if (r < grid_dim-1 && free_spots[r+1][c]) {
            int nr = r + 1, nc = c;
            if (d[nr][nc] > dist + 1) {
                bool cond1 = (nr == tr && nc == tc && step_cnt[nr][nc] >= dist + 1);
                bool cond2 = (!(nr == tr && nc == tc) && step_cnt[nr][nc] > dist + 1);
                if (cond1 || cond2) q.push({dist + 1, {nr, nc}});
            }
        }
        if (c < grid_dim-1 && free_spots[r][c+1]) {
            int nr = r, nc = c + 1;
            if (d[nr][nc] > dist + 1) {
                bool cond1 = (nr == tr && nc == tc && step_cnt[nr][nc] >= dist + 1);
                bool cond2 = (!(nr == tr && nc == tc) && step_cnt[nr][nc] > dist + 1);
                if (cond1 || cond2) q.push({dist + 1, {nr, nc}});
            }
        }
    }
    return d[tr][tc];
}

void link_nodes(int a, int b, int cap) {
    el.push_back({a, b, cap, 0});
    el.push_back({b, a, 0, 0});
    g[a].push_back((int)el.size() - 2);
    g[b].push_back((int)el.size() - 1);
}

bool build_level_graph() {
    fill(level_, level_ + grid_dim * grid_dim * 2 + 2, -1);
    queue<int> q;
    q.push(0);
    level_[0] = 0;
    while (!q.empty() && level_[grid_dim * grid_dim * 2 + 1] == -1) {
        int u = q.front(); q.pop();
        for (int eid : g[u]) {
            int v = el[eid].v;
            if (level_[v] == -1 && el[eid].flow < el[eid].cap) {
                level_[v] = level_[u] + 1;
                q.push(v);
            }
        }
    }
    return level_[grid_dim * grid_dim * 2 + 1] != -1;
}

int push_flow(int u, int limit) {
    if (!limit) return 0;
    if (u == grid_dim * grid_dim * 2 + 1) return limit;
    for (; idx[u] < (int)g[u].size(); ++idx[u]) {
        int eid = g[u][idx[u]];
        int v = el[eid].v;
        if (level_[v] != level_[u] + 1) continue;
        int delta = push_flow(v, min(limit, el[eid].cap - el[eid].flow));
        if (delta) {
            el[eid].flow += delta;
            el[eid ^ 1].flow -= delta;
            return delta;
        }
    }
    return 0;
}

int dinic_algo() {
    int res = 0;
    while (build_level_graph()) {
        fill(idx, idx + grid_dim * grid_dim * 2 + 2, 0);
        int x;
        while ((x = push_flow(0, U)) > 0) res += x;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> grid_dim >> max_time;
    queue<pair<int, pair<int, int>>> q;
    char val;
    int node_counter = 1;
    for (int i = 0; i < grid_dim; ++i) {
        for (int j = 0; j < grid_dim; ++j) {
            cin >> val;
            step_cnt[i][j] = max_time;
            if (val == 'Z') {
                ex_r = i;
                ex_c = j;
                free_spots[i][j] = false;
            } else if (val == 'Y') {
                free_spots[i][j] = false;
            } else {
                free_spots[i][j] = true;
            }
            link_nodes(0, node_counter++, (val == 'Z' || val == 'Y') ? 0 : val - '0');
        }
    }
    node_counter = grid_dim * grid_dim + 1;
    for (int i = 0; i < grid_dim; ++i) {
        for (int j = 0; j < grid_dim; ++j) {
            cin >> val;
            if (val >= '0' && val <= '9') flow_cap[i][j] = val - '0';
            link_nodes(node_counter++, grid_dim * grid_dim * 2 + 1, (val == 'Z' || val == 'Y') ? 0 : val - '0');
        }
    }
    q.push({0, {ex_r, ex_c}});
    while (!q.empty()) {
        int d = q.front().first;
        int r = q.front().second.first;
        int c = q.front().second.second;
        q.pop();
        step_cnt[r][c] = d;
        if (r > 0 && d + 1 < step_cnt[r - 1][c] && free_spots[r - 1][c])
            q.push({d + 1, {r - 1, c}});
        if (c > 0 && d + 1 < step_cnt[r][c - 1] && free_spots[r][c - 1])
            q.push({d + 1, {r, c - 1}});
        if (r < grid_dim - 1 && d + 1 < step_cnt[r + 1][c] && free_spots[r + 1][c])
            q.push({d + 1, {r + 1, c}});
        if (c < grid_dim - 1 && d + 1 < step_cnt[r][c + 1] && free_spots[r][c + 1])
            q.push({d + 1, {r, c + 1}});
    }
    int node_id = 0;
    for (int i = 0; i < grid_dim; ++i) {
        for (int j = 0; j < grid_dim; ++j) {
            int sink_id = grid_dim * grid_dim;
            ++node_id;
            for (int x = 0; x < grid_dim; ++x) {
                for (int y = 0; y < grid_dim; ++y) {
                    ++sink_id;
                    if (free_spots[i][j] && free_spots[x][y] && shortest_path(i, j, x, y) <= max_time)
                        link_nodes(node_id, sink_id, U);
                }
            }
        }
    }
    cout << dinic_algo() << '\n';
    return 0;
}
